WITH ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY job_title ORDER BY salary DESC) AS rank_in_group FROM employees) x WHERE rank_in_group = 1) SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, DATE_TRUNC('YEAR', hire_date) AS year_start, COUNT(DISTINCT level) AS distinct_levels, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, SIZE(COLLECT_SET(level)) AS num_levels, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', hire_date) ORDER BY COUNT(DISTINCT level) DESC) AS distinct_levels_percent_rank FROM ranked GROUP BY 1, 2;
